import {PUZZLES,CORE,PEOPLE,VIGENERE_TEXT} from './content.mjs';
import * as E from './engine.mjs';
import * as V from './views.mjs';
import {ArchiveRoom} from './room.mjs';
const SAVE='ninth-record-case-v1',SETTINGS='ninth-record-settings';
const icons={folder:'<path d="M3 6h7l2 3h9v12H3zM3 6V3h7l2 3"/>',board:'<path d="M3 3h18v15H3zM8 21h8M12 18v3M6 6h4v4H6zm8 5h4v4h-4zM10 8l4 5"/>',terminal:'<path d="M3 3h18v14H3zM7 21h10M12 17v4M6 7l3 3-3 3m5 0h6"/>',tools:'<path d="M8 3h8v4H8zM5 7h14v14H5zM9 11h6m-6 4h6m-6 3h3"/>',letter:'<path d="M3 5h18v15H3zM3 5l9 8 9-8"/>',notes:'<path d="M5 3h14v18H5zM8 7h8m-8 4h8m-8 4h5"/>'};
export function createArchive({document:doc=globalThis.document,window:win=globalThis.window,roomFactory=(canvas,c)=>new ArchiveRoom(canvas,c)}={}){
 const $=id=>doc.getElementById(id);let state;try{state=E.restore(win.localStorage.getItem(SAVE));}catch{state=E.fresh();}let settings;try{settings=JSON.parse(win.localStorage.getItem(SETTINGS))||{};}catch{settings={};}let room=null,view='room',active=null,page=0,previousPuzzle=null,started=false,toastTimer,boardDrag=null,alignment={x:25,y:70},storageAvailable=true;
 function save(syncRoom=false){try{win.localStorage.setItem(SAVE,JSON.stringify(state));$('save-status').textContent='PROGRESS SAVED ON THIS BROWSER';storageAvailable=true;}catch{$('save-status').textContent='SESSION ONLY · EXPORT TO KEEP YOUR CASE';storageAvailable=false;}if(syncRoom)room?.sync(state);updateHeader();}
 function updateHeader(){$('role-label').textContent=E.role(state);$('score-label').innerHTML=E.score(state)+' <small>PTS</small>';$('researcher-name').value=state.alias;$('enter-archive').textContent=state.solved.length?'Continue the investigation':'Accept the invitation';const open=PUZZLES.find(p=>!state.solved.includes(p.id)&&E.available(state,p.id)&&!p.optional);$('room-prompt').textContent=state.solved.includes('synthesis')?'The case is complete. The record—and its open question—survives.':open?'Next open record: '+open.title+'.':'Pin your verified findings to complete the board.';}
 function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');win.clearTimeout(toastTimer);toastTimer=win.setTimeout(()=>$('toast').classList.remove('visible'),3600);}
 function cue(name='verified'){if(!settings.sound)return;try{const a=new win.Audio(`assets/ninth/audio/${name}.wav`);a.volume=.28;const p=a.play();p?.catch?.(()=>{});}catch{}}
 function start(){state.alias=($('researcher-name').value||'Researcher').trim().slice(0,28)||'Researcher';started=true;$('intro').hidden=true;save();room?.view('desk');if(settings.sound)playAmbient();if(!state.solved.length)openPuzzle('invitation');else toast('Welcome back, '+state.alias+'. Your record is preserved.');}
 function home(){if($('panel').open)$('panel').close();started=false;$('intro').hidden=false;room?.view('room');updateHeader();$('enter-archive').focus();}
 function playAmbient(){const audio=$('room-audio');audio.volume=.15;audio.play()?.catch?.(()=>{});}
 function toggleSound(){settings.sound=!settings.sound;try{win.localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch{}$('sound-button').textContent=settings.sound?'Sound on':'Sound off';$('sound-button').setAttribute('aria-pressed',String(!!settings.sound));if(settings.sound){playAmbient();cue('paper');}else $('room-audio').pause();}
 async function fullscreen(){try{if(doc.fullscreenElement)await doc.exitFullscreen();else await doc.documentElement.requestFullscreen();}catch{toast('Fullscreen is unavailable here. The archive remains playable.');}}
 function display(title,body,kicker='ASTER / CONSERVATION COPY'){const panel=$('panel');$('panel-title').textContent=title;$('panel-kicker').textContent=kicker;$('panel-content').innerHTML=body;$('panel-back').hidden=!(previousPuzzle&&view!=='puzzle');if(!panel.open)panel.showModal();$('panel-content').scrollTop=0;room?.pause(true);bindCommon();}
 function close(){if($('panel').open)$('panel').close();}
 function show(name,extra){if(name==='puzzle'){openPuzzle(extra);return;}if(name==='room'){close();return;}if(name==='home'){home();return;}if(name==='export'){exportSave();return;}previousPuzzle=active;active=null;view=name;let title='',body='';switch(name){case 'records':title='The working dossier';body=V.records(state,extra||'all');room?.view('desk');break;case 'board':title='The evidence board';body=V.boardView(state);room?.view('board');break;case 'terminal':title='Conservation terminal';body=V.terminalView(state);room?.view('terminal');break;case 'tools':title='The reference drawer';body=V.toolsView();room?.view('tools');break;case 'letters':title='Correspondence';body=V.correspondence(state);break;case 'ledger':title='Personal case ledger';body=V.ledgerView(state)+`<button data-action="reset" class="danger-link">Start a new case</button>`;break;case 'sources':title='Source & fiction notes';body=V.sourcesView();break;case 'help':title='The field manual';body=V.helpView();break;case 'notes':title='Private working notes';body=`<div class="section-intro"><p class="eyebrow">YOUR WORKING COPY / LOCAL TO THIS BROWSER</p><h2>What do you think happened?</h2><p>Your notes save as you type. Keep observations separate from interpretations.</p></div><label for="private-notes" class="eyebrow">PRIVATE NOTES</label><textarea id="private-notes" class="private-notes" maxlength="16000" placeholder="Observed fact / source / interpretation / question…">${V.esc(state.notes)}</textarea><p class="widget-note">Use the ledger to export these notes with your case. Escape returns to the room.</p>`;break;case 'resolution':if(!state.solved.includes('synthesis')){show('board');return;}title='The completed ninth record';body=V.resolution(state);break;case 'reset':title='Start a new case?';body='<div class="section-intro"><h2>Preserve a copy before starting again.</h2><p>A new case clears the progress and notes saved in this browser. Export first if you want to keep this investigation.</p></div><div class="reset-actions"><button data-action="export" class="secondary-button">Export current case</button><button id="confirm-reset" class="primary-button">Begin a new case</button><button data-action="ledger" class="secondary-button">Keep investigating</button></div>';break;default:return;}display(title,body);bindView();}
 function selectObject(action){if(!started){start();return;}const filters=['dossier','radio','cabinet','drawer','lamp','chart'];if(filters.includes(action)){const open=PUZZLES.filter(p=>p.object===action&&E.available(state,p.id));if(open.length===1)openPuzzle(open[0].id);else show('records',action);}else show(action==='board'?'board':action==='tools'?'tools':'terminal');}
 function openPuzzle(id){const p=E.puzzle(id);if(!p)return;if(E.status(state,id)==='locked'){toast(id==='synthesis'?'Solve and pin the nine earlier core records first.':'Follow the earlier records to open this dossier.');return;}previousPuzzle=null;active=id;page=state.solved.includes(id)?1:0;view='puzzle';alignment={x:25,y:70};renderPuzzle();room?.view(id==='synthesis'?'board':p.object==='terminal'?'terminal':'desk');}
 function renderPuzzle(){const p=E.puzzle(active);if(!p)return;display('Dossier '+p.number+' / '+p.title,V.puzzleView(state,p,page),p.optional?'OPTIONAL TECHNICAL BRANCH':'ASTER / WORKING DOSSIER');bindPuzzle(p);}
 function bindCommon(){doc.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>show(b.dataset.action));doc.querySelectorAll('[data-open-puzzle]').forEach(b=>b.onclick=()=>openPuzzle(b.dataset.openPuzzle));doc.querySelectorAll('[data-print]').forEach(b=>b.onclick=()=>win.print());}
 function bindView(){if(view==='board')bindBoard();if(view==='tools')bindTools();if(view==='notes')$('private-notes').oninput=()=>{state.notes=$('private-notes').value;save();};if(view==='ledger')$('import-case').onchange=importSave;if(view==='reset')$('confirm-reset').onclick=()=>{state=E.fresh();save(true);close();home();toast('A fresh conservation copy is ready.');};}
 function bindPuzzle(p){doc.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=Number(b.dataset.page);renderPuzzle();});$('request-hint').onclick=()=>{const h=E.hint(state,p.id);if(h){save();$('hint-copy').textContent=h.text;$('request-hint').textContent=h.level===3?'Full solution shown':'Next hint ('+h.level+'/3)';cue('paper');}};if($('pin-artifact'))$('pin-artifact').onclick=()=>pinOne(p.id);if(doc.querySelector('[data-next-lead]'))doc.querySelector('[data-next-lead]').onclick=()=>{const next=PUZZLES.find(q=>!state.solved.includes(q.id)&&!q.optional&&E.available(state,q.id));if(next)openPuzzle(next.id);else show('board');};if($('answer-form'))$('answer-form').onsubmit=async e=>{e.preventDefault();await submit(p);};if(p.type==='wordle'&&$('fresh-wordle'))$('fresh-wordle').onclick=()=>{state.wordle=[];save();renderPuzzle();};if(p.type==='sudoku')doc.querySelectorAll('[data-cell]').forEach(input=>{input.oninput=()=>{const i=Number(input.dataset.cell);input.value=input.value.replace(/[^1-4]/g,'').slice(-1);state.sudoku[i]=Number(input.value)||0;save();};input.onkeydown=e=>{const i=Number(input.dataset.cell),offset={ArrowLeft:-1,ArrowRight:1,ArrowUp:-4,ArrowDown:4}[e.key];if(offset&&i+offset>=0&&i+offset<16){e.preventDefault();doc.querySelector(`[data-cell="${i+offset}"]`)?.focus();}};});if(p.type==='alignment'&&!state.solved.includes(p.id))bindAlignment();if(p.type==='caesar'&&$('cipher-shift'))$('cipher-shift').oninput=()=>{$('shift-value').textContent=$('cipher-shift').value;$('cipher-output').textContent=E.caesar('GR QRW WUXVW WKH GDWH',-Number($('cipher-shift').value));};if(p.type==='morse'&&$('audio-speed'))$('audio-speed').onchange=()=>{$('recording').playbackRate=Number($('audio-speed').value);};if(p.type==='receipt'&&!state.solved.includes(p.id))bindDigests();}
 async function submit(p){let result;const beforeRole=E.role(state),beforeScore=E.score(state);if(p.type==='wordle')result=E.guessWord(state,$('answer').value);else{let input=$('answer')?.value;if(p.type==='sudoku')input=[...doc.querySelectorAll('[data-cell]')].map(c=>Number(c.value)||0);if(p.type==='alignment')input={...alignment,answer:$('answer').value};if(p.type==='receipt')input=doc.querySelector('input[name="receipt"]:checked')?.value;if(p.type==='synthesis')input={method:$('final-method').value,primary:$('final-primary').value,signal:$('final-signal').value};try{result=await E.verify(state,p.id,input);}catch{result={ok:false,message:'The verifier could not run here. Use the local HTTP server or HTTPS, then retry; your progress is safe.'};}}if(result.ok&&p.id==='synthesis')E.pin(state,p.id);save(true);if(result.ok){page=1;renderPuzzle();cue('verified');const promotion=beforeRole!==E.role(state)?' · '+E.role(state):'';toast('Verified · +'+(E.score(state)-beforeScore)+' points'+promotion);if(p.id==='synthesis'){show('resolution');cue('final-signal');}}else{if(p.type==='wordle')renderPuzzle();$('answer-status').textContent=result.message;$('answer-status').classList.add('shown');}}
 function pinOne(id){const before=E.connections(state).length;if(E.pin(state,id)){save(true);cue('pin');toast('Pinned · +15 points'+(E.connections(state).length>before?' · '+(E.connections(state).length-before)+' new connection'+(E.connections(state).length-before>1?'s':''):''));}if(view==='puzzle')renderPuzzle();else show('board');}
 function bindBoard(){const pinAll=$('pin-all');pinAll.onclick=()=>{const before=E.connections(state).length;let count=0;for(const id of state.solved)if(E.pin(state,id))count++;save(true);show('board');toast(count?count+' records pinned · '+(E.connections(state).length-before)+' connections established':'All verified records are already pinned.');};const board=$('evidence-board');doc.querySelectorAll('[data-board-card]').forEach(card=>{card.onclick=()=>{if(!boardDrag?.moved)openPuzzle(card.dataset.boardCard);};card.onpointerdown=e=>{if(e.button!==0)return;boardDrag={id:card.dataset.boardCard,x:e.clientX,y:e.clientY,moved:false};card.setPointerCapture(e.pointerId);};card.onpointermove=e=>{if(!boardDrag||boardDrag.id!==card.dataset.boardCard)return;if(Math.hypot(e.clientX-boardDrag.x,e.clientY-boardDrag.y)>5)boardDrag.moved=true;if(!boardDrag.moved)return;const r=board.getBoundingClientRect(),pos={x:Math.max(.08,Math.min(.92,(e.clientX-r.left)/r.width)),y:Math.max(.08,Math.min(.92,(e.clientY-r.top)/r.height))};state.boardPositions[boardDrag.id]=pos;card.style.left=pos.x*100+'%';card.style.top=pos.y*100+'%';redrawThreads();};card.onpointerup=()=>{save(true);win.setTimeout(()=>boardDrag=null,0);};card.onpointercancel=()=>{boardDrag=null;save(true);};});}
 function redrawThreads(){const svg=$('board-threads');if(!svg)return;svg.innerHTML=E.connections(state).map(([a,b])=>{const pa=V.positionFor(state,a),pb=V.positionFor(state,b);return `<path d="M${pa.x*1000} ${pa.y*800} Q${(pa.x+pb.x)*500} ${(pa.y+pb.y)*400+24} ${pb.x*1000} ${pb.y*800}"/>`;}).join('');}
 function bindAlignment(){const update=()=>{alignment={x:Number($('align-x').value),y:Number($('align-y').value)};$('align-x-value').textContent=alignment.x;$('align-y-value').textContent=alignment.y;$('tracing-layer').style.transform=`translate(${(alignment.x-62)*.7}px,${(alignment.y-38)*.7}px)`;const ok=Math.abs(alignment.x-62)<=4&&Math.abs(alignment.y-38)<=4;$('align-status').textContent=ok?'Registration marks aligned. Read the signature and verify it.':'Bring the three crosses together. You can drag the tracing or use the sliders.';$('alignment-mat').classList.toggle('aligned',ok);};$('align-x').oninput=$('align-y').oninput=update;let drag;const layer=$('tracing-layer');layer.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,px:alignment.x,py:alignment.y};layer.setPointerCapture(e.pointerId);};layer.onpointermove=e=>{if(!drag)return;$('align-x').value=Math.max(0,Math.min(100,drag.px+(e.clientX-drag.x)/.7));$('align-y').value=Math.max(0,Math.min(100,drag.py+(e.clientY-drag.y)/.7));update();};layer.onpointerup=layer.onpointercancel=()=>drag=null;update();}
 async function bindDigests(){const payloads={press:'ASTER PUBLIC SUMMARY / PREDICTION CLAIM / LATER PUBLICITY',typed:'ASTER TYPED COPY / NORMALIZED DATES / NO ORIGINAL LOG',ix:'RECEIVER LOG / ECHO / RETAINED UNDER IX'};const reference=await E.digest(payloads.ix);if(!$('original-digest'))return;$('original-digest').textContent=reference;doc.querySelectorAll('[data-check-digest]').forEach(b=>b.onclick=async()=>{const actual=await E.digest(payloads[b.dataset.checkDigest]);if($('digest-status'))$('digest-status').textContent=(actual===reference?'Exact content match. ':'Different content digest. ')+actual;});}
 function bindTools(){const caesar=()=>{$('tool-caesar-output').textContent=E.caesar($('tool-caesar-text').value,-Number($('tool-caesar-shift').value));};$('tool-caesar-text').oninput=$('tool-caesar-shift').oninput=caesar;caesar();const vig=()=>{$('tool-vigenere-output').textContent=E.vigenere($('tool-vigenere-text').value,$('tool-vigenere-key').value)||'Enter a repeating key.';};$('tool-vigenere-text').oninput=$('tool-vigenere-key').oninput=vig;vig();}
 async function exportSave(){const text=await E.exportCase(state),blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=doc.createElement('a');a.href=url;a.download='ninth-record-case.json';a.click();URL.revokeObjectURL(url);toast('Case file exported, including your notes and board.');}
 async function importSave(){const file=$('import-case').files?.[0];if(!file)return;try{const imported=await E.importCase(await file.text());display('Replace this browser’s case?',`<div class="section-intro"><h2>Import ${V.esc(imported.alias)}’s case?</h2><p>The file contains ${imported.solved.length} verified records and ${E.score(imported)} points. Importing replaces the case currently saved in this browser.</p></div><div class="reset-actions"><button id="confirm-import" class="primary-button">Import this case</button><button data-action="ledger" class="secondary-button">Keep the current case</button></div>`);$('confirm-import').onclick=()=>{state=imported;save(true);show('ledger');toast('Case restored.');};}catch(e){toast(e.message||'This case file could not be imported.');}}
 bindCommon();doc.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round">${icons[el.dataset.icon]||''}</svg>`);$('intro-form').onsubmit=e=>{e.preventDefault();start();};$('close-panel').onclick=close;$('panel').addEventListener('close',()=>{room?.pause(false);active=null;previousPuzzle=null;view='room';$('object-hint').hidden=true;if(started)$('archive-room').focus();});$('panel').addEventListener('click',e=>{if(e.target!==$('panel'))return;const r=$('panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();});$('panel-back').onclick=()=>{if(previousPuzzle)openPuzzle(previousPuzzle);};$('home-button').onclick=home;$('profile-button').onclick=()=>show('ledger');$('help-button').onclick=()=>show('help');$('sound-button').onclick=toggleSound;$('fullscreen-button').onclick=fullscreen;$('reset-camera').onclick=()=>room?.view('room');
 doc.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;const typing=e.target?.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName);if(e.key==='Escape'){if($('panel').open){e.preventDefault();close();}return;}if(typing)return;const key=e.key.toLowerCase(),actions={'1':'records','2':'board','3':'terminal','4':'tools',h:'help','?':'help',l:'ledger',n:'notes'};if(actions[key]){e.preventDefault();show(actions[key]);}else if(key==='f'){e.preventDefault();fullscreen();}});
 try{room=roomFactory($('archive-room'),{select:selectObject,hover:action=>{const el=$('object-hint');el.hidden=!action||$('panel').open||!started;el.textContent=({dossier:'Inspect the working dossier',drawer:'Open the shelf-index drawer',radio:'Examine the receiver tape',lamp:'Use the inspection mat',terminal:'Open the conservation terminal',cabinet:'Inspect the records cabinet',chart:'Examine the atomic timeline',board:'Review your evidence connections',tools:'Open the reference drawer'}[action]||'Inspect');},progress:n=>{$('loading-progress').style.width=n*100+'%';$('loading-label').textContent=n===1?'CONSERVATION ROOM READY':'PREPARING ORIGINAL 3D OBJECTS · '+Math.round(n*100)+'%';},fallback:name=>{if(name==='context'){$('fallback-room').hidden=false;toast('Use the archive navigation while the 3D room is unavailable.');}}});room.sync(state);}catch(e){$('fallback-room').hidden=false;$('loading-label').textContent='FLAT ARCHIVE READY / THE COMPLETE CASE IS AVAILABLE';$('loading-progress').style.width='100%';console.warn('3D view unavailable; flat archive remains active.',e);}
 $('sound-button').textContent=settings.sound?'Sound on':'Sound off';$('sound-button').setAttribute('aria-pressed',String(!!settings.sound));updateHeader();save();const timer=win.setInterval(()=>{if(started&&!doc.hidden){state.playedSeconds+=15;save();}},15000);return {getState:()=>state,show,openPuzzle,start,submit,save,close,getRoom:()=>room,isStorageAvailable:()=>storageAvailable,destroy(){win.clearInterval(timer);room?.renderer?.dispose();}};
}
if(typeof document!=='undefined')createArchive();
